merge into apx_demo_roles t
using (select 'REQUESTER' role_code, 'Requester' role_name from dual) s
   on (t.role_code = s.role_code)
 when matched then update set t.role_name = s.role_name
 when not matched then insert (role_code, role_name) values (s.role_code, s.role_name);

