merge into apx_demo_doc_types t
using (select 'REQ' doc_type, 'Permintaan Barang' doc_name, 'REQ' prefix, 'APX_DEMO_REQUESTS' table_name, 'REQUEST_ID' pk_column, 'REQUEST_NO' number_column, 'STATUS' status_column, '(select nvl(sum(l.line_amount), 0) from apx_demo_request_lines l where l.request_id = t.request_id)' amount_expr, 'apx_demo_request_pkg.check_submit' validate_proc, 'MANAGER' approver1_role, 'DIRECTOR' approver2_role, 10000000 level2_limit from dual) s
   on (t.doc_type = s.doc_type)
 when matched then update set t.doc_name = s.doc_name, t.table_name = s.table_name, t.pk_column = s.pk_column, t.number_column = s.number_column, t.status_column = s.status_column, t.amount_expr = s.amount_expr, t.validate_proc = s.validate_proc
 when not matched then insert (doc_type, doc_name, prefix, table_name, pk_column, number_column, status_column, amount_expr, validate_proc, approver1_role, approver2_role, level2_limit) values (s.doc_type, s.doc_name, s.prefix, s.table_name, s.pk_column, s.number_column, s.status_column, s.amount_expr, s.validate_proc, s.approver1_role, s.approver2_role, s.level2_limit);

